from pathlib import Path
from unittest.mock import patch
sys.path[:0]=['.wavefoundry/framework/scripts']
import sqlite_vector_store as vs,index_state_store as iss
rng=random.Random(1793)
sequence=[];expected={}
for n in range(650):
    key=str(rng.randrange(80));kind=rng.choice(['row','id','path'])
    if n in (0,310):kind='replace'
    sequence.append((kind,key,n))
    if kind=='replace':expected.clear()
    elif kind=='row':expected[key]=str(n)
    elif kind=='id':expected.pop(key,None)
    else:
        for k in list(expected):
            if int(k)%7==int(key)%7:del expected[k]
outputs=[]
for limit in [64*1024*1024,4096,0]:
    with tempfile.TemporaryDirectory() as tmp,patch.object(vs.PreparedUpdates,'MEMORY_LIMIT_BYTES',limit):
        path=Path(tmp);store=iss.IndexStateStore(path)
        with vs.PreparedUpdates(path) as prepared:
            for kind,key,n in sequence:
                kw={'replace':True} if kind=='replace' else {'ids':[key]} if kind=='id' else {'paths':[f'{int(key)%7}.py']} if kind=='path' else {'rows':[dict(id=key,path=f'{int(key)%7}.py',text=str(n),kind='code',vector=[1.]+[0.]*383)]}
